def lemonade_change_brute(bills):
    on_hand = []
    for bill in bills:
        if bill == 5:
            on_hand.append(5)
            continue
        needed = bill - 5
        # search for ANY combination of bills on hand summing to `needed`
        found = False
        on_hand.sort(reverse=True)
        remaining = needed
        used = []
        for b in on_hand:
            if b <= remaining:
                remaining -= b
                used.append(b)
            if remaining == 0:
                found = True
                break
        if not found:
            return False
        for b in used:
            on_hand.remove(b)
        on_hand.append(bill)
    return True

