def lemonade_change(bills):
    five = ten = 0
    for bill in bills:
        if bill == 5:
            five += 1
        elif bill == 10:
            if five == 0:
                return False
            five -= 1
            ten += 1
        else:                                          # bill == 20
            if ten > 0 and five > 0:
                ten -= 1
                five -= 1                                # prefer $10 + $5
            elif five >= 3:
                five -= 3                                 # fall back to three $5s
            else:
                return False
    return True

