public class Main {
    static boolean lemonadeChange(int[] bills) {
        int five = 0, ten = 0;
        for (int bill : bills) {
            if (bill == 5) five++;
            else if (bill == 10) {
                if (five == 0) return false;
                five--; ten++;
            } else {                                            // bill == 20
                if (ten > 0 && five > 0) { ten--; five--; }         // prefer $10 + $5
                else if (five >= 3) five -= 3;                       // fall back to three $5s
                else return false;
            }
        }
        return true;
    }
}

